package com.nthexperience.desktop;

import android.content.Context;
import android.graphics.Typeface;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Licensed bundled face and Android families; no Windows-only font names are substituted. */
final class TenFonts extends LinearLayout {
 static final String KEY="ten_font";
 static final String[][] FAMILIES={{"selawik","Selawik","Bundled · Regular, Semibold"},{"sans-serif","Sans Serif","Android · Regular, Bold"},{"sans-serif-light","Sans Serif Light","Android · Light"},{"sans-serif-thin","Sans Serif Thin","Android · Thin"},{"sans-serif-medium","Sans Serif Medium","Android · Medium"},{"sans-serif-condensed","Sans Serif Condensed","Android · Regular, Bold"},{"serif","Serif","Android · Regular, Bold, Italic"},{"monospace","Monospace","Android · Regular, Bold"},{"cursive","Cursive","Android · Device fallback"},{"sans-serif-smallcaps","Small Caps","Android · Device fallback"}};
 final DesktopStore store;final EditText query,sample;final GridLayout grid;int columns=1;final Runnable changed;
 TenFonts(Context c,DesktopStore store,Runnable changed){super(c);this.store=store;this.changed=changed;setOrientation(VERTICAL);setContentDescription("Available fonts");TextView note=Aero.text(c,"Preview and choose the text used across Nth Desktop Ten.",12,0xff666666);addView(note);TextView heading=Aero.text(c,"Available fonts",19,Aero.INK);heading.setPadding(0,Aero.dp(c,20),0,Aero.dp(c,12));addView(heading);query=new EditText(c);query.setSingleLine();query.setTextSize(13);query.setHint("Type here to search.");query.setContentDescription("Search available fonts");addView(query,new LayoutParams(-1,Aero.dp(c,44)));sample=new EditText(c);sample.setSingleLine();sample.setTextSize(12);sample.setHint("Type your own preview text");sample.setContentDescription("Font preview text");addView(sample,new LayoutParams(-1,Aero.dp(c,44)));grid=new GridLayout(c);grid.setColumnCount(1);addView(grid,new LayoutParams(-1,-2));TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int n,int z){}public void onTextChanged(CharSequence s,int a,int b,int n){render();}public void afterTextChanged(Editable e){}};query.addTextChangedListener(watcher);sample.addTextChangedListener(watcher);addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int next=r-l>=Aero.dp(c,570)?3:r-l>=Aero.dp(c,300)?2:1;if(next!=columns){columns=next;render();}});render();}
 static boolean valid(String id){for(String[] row:FAMILIES)if(row[0].equals(id))return true;return false;}
 static Typeface face(Context c,String id,boolean bold){if(id.equals("selawik")){try{return Typeface.createFromAsset(c.getAssets(),bold?"fonts/selawksb.ttf":"fonts/selawk.ttf");}catch(RuntimeException ignored){id="sans-serif";}}return Typeface.create(id,bold?Typeface.BOLD:Typeface.NORMAL);}
 void render(){grid.removeAllViews();grid.setColumnCount(columns);String q=query.getText().toString().toLowerCase(Locale.ROOT);int n=0;for(String[] font:FAMILIES){if(!font[1].toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout tile=Aero.column(getContext());tile.setPadding(Aero.dp(getContext(),8),Aero.dp(getContext(),14),Aero.dp(getContext(),8),Aero.dp(getContext(),14));tile.setBackground(Aero.selection(getContext()));TextView preview=Aero.text(getContext(),sample.length()==0?"The quick brown fox jumps over the lazy dog.":sample.getText().toString(),24,Aero.INK);preview.setTag("ten-font-preview");preview.setTypeface(face(getContext(),font[0],false));preview.setMaxLines(4);preview.setEllipsize(TextUtils.TruncateAt.END);tile.addView(preview,new LayoutParams(-1,Aero.dp(getContext(),136)));boolean selected=store.prefs.getString(KEY,"selawik").equals(font[0]);tile.addView(Aero.text(getContext(),font[1]+(selected?"  ✓":""),13,Aero.INK));tile.addView(Aero.text(getContext(),font[2],10,0xff666666));tile.setContentDescription("Use font "+font[1]);tile.setFocusable(true);tile.setOnClickListener(v->{store.prefs.edit().putString(KEY,font[0]).apply();Aero.resetFont();changed.run();});GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(n/columns),GridLayout.spec(n%columns,1f));p.width=0;p.height=-2;p.setMargins(0,Aero.dp(getContext(),8),Aero.dp(getContext(),8),0);grid.addView(tile,p);n++;}if(n==0)grid.addView(Aero.text(getContext(),"No matching fonts.",13,Aero.INK));}
 static void apply(View view){if(view instanceof TextView&&!"ten-font-preview".equals(view.getTag())){TextView text=(TextView)view;Typeface old=text.getTypeface();int style=old==null?Typeface.NORMAL:old.getStyle();text.setTypeface(Typeface.create(Aero.face(view.getContext()),style));}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)apply(group.getChildAt(i));}}
}
